export type ToolFaq = { q: string; a: string };
export type ToolSeoArticleSection = { heading: string; paragraphs: string[]; bullets?: string[] };
/**
 * Keep search snippets readable: never cut an English word in half, and avoid
 * appending an ellipsis after trailing punctuation. CJK descriptions without
 * spaces are safely clipped by character count.
 */
export function fitSeoMetaDescription(value: string, maxLength = 158): string {
  const normalized = value.replace(/\\s+/g, ' ').trim();
  if (normalized.length <= maxLength) return normalized;
  const clipped = normalized.slice(0, Math.max(1, maxLength - 1));
  const lastSpace = clipped.lastIndexOf(' ');
  const readable = lastSpace >= Math.floor(maxLength * 0.65)
    ? clipped.slice(0, lastSpace)
    : clipped;
  return readable.replace(/[.,;:!?-]+$/g, '').trimEnd() + '…';
}

export type ToolSeoContent = {
  articleSections?: ToolSeoArticleSection[];
  /** Short hero description matching the English tool page's tool.description. */
  heroIntro?: string;
  intro: string;
  why: string;
  steps: string[];
  useCases: string[];
  tips: string[];
  limitations: string[];
  faq: ToolFaq[];
  visual: 'workflow' | 'finance' | 'formats' | 'code' | 'text' | 'youtube' | 'converter';
  formula?: string;
};

const makeFaqs = (tool: ToolMeta, extras: ToolFaq[]): ToolFaq[] => {
  const faqs: ToolFaq[] = [
    {
      q: 'What is ' + tool.name + ' used for?',
      a: tool.description + ' It is designed for a focused workflow so you can complete the task without installing a separate desktop utility. The exact output depends on the values, files, or code you provide.',
    },
    {
      q: 'How does ' + tool.name + ' work?',
      a: 'Enter the required input in the workspace, review the available options, run the operation, and inspect the result. Where browser-side processing is supported, the work is performed in the browser; execution or external-runtime requirements are indicated by the tool.',
    },
    ...extras,
    {
      q: 'Is ' + tool.name + ' free to use?',
      a: 'Yes. The tool is available without a paid account. Practical limits can come from browser memory, device performance, input size, or any third-party execution service used by a particular workflow.',
    },
    {
      q: 'Can I use ' + tool.name + ' on a phone or tablet?',
      a: 'The page is responsive and designed for modern browsers. Very large files, complex calculations, or compute-heavy operations can behave differently depending on the device.',
    },
  ];
  if (faqs.length > 6) return faqs.slice(0, 6);
  if (faqs.length % 2 === 1) {
    faqs.push({
      q: 'What should I check before using the result from ' + tool.name + '?',
      a: 'Review the result against the original input and intended use. For important documents, calculations, code, or decisions, verify the final output with the relevant authoritative source or target environment.',
    });
  }
  return faqs;
};

